const shopImg=(image,label)=>`<img src="nui://ox_inventory/web/images/${encodeURIComponent(image)}" alt="${esc(label)}" onerror="this.onerror=null;this.classList.add('missing');this.removeAttribute('src')">`;
function categoryMeta(luna=true){return[{key:'all',label:'All Products',sub:luna?'Browse our full collection':'Everything on the counter'},{key:'seeds',label:'Seeds',sub:'Start something new'},{key:'soil',label:'Soil',sub:'Nourish your roots'},{key:'fertilizer',label:'Fertilizer',sub:'Help them thrive'},{key:'pots',label:'Pots',sub:'A home for every plant'},{key:'tools',label:'Tools',sub:'For a greener tomorrow'}]}
function filteredShopItems(shop){const items=shopItems(shop),search=String(ui.customerFilters.search||'').trim().toLowerCase(),category=ui.customerFilters.category||'all';let rows=items.filter(item=>{if(category!=='all'&&categoriseItem(item)!==category)return false;if(search&&!(`${item.name} ${item.label}`.toLowerCase().includes(search)))return false;return true});const sort=ui.customerFilters.sort||'featured';if(sort==='name')rows.sort((a,b)=>a.label.localeCompare(b.label));else if(sort==='price_asc')rows.sort((a,b)=>a.price-b.price||a.label.localeCompare(b.label));else if(sort==='price_desc')rows.sort((a,b)=>b.price-a.price||a.label.localeCompare(b.label));else rows.sort((a,b)=>{const af=categoriseItem(a)==='seeds'?0:1,bf=categoriseItem(b)==='seeds'?0:1;return af-bf||a.label.localeCompare(b.label)});return rows}
function findCartLine(name){return(ui.customerCart||[]).find(line=>String(line.itemName)===String(name))||null}
function cartItemCount(){return(ui.customerCart||[]).reduce((sum,line)=>sum+safeInt(line.qty,1,9999,1),0)}
function cartSubtotal(){return(ui.customerCart||[]).reduce((sum,line)=>sum+(safeInt(line.qty,1,9999,1)*safeInt(line.price,0,100000000,0)),0)}
function syncCartAgainstShop(shop){const byName=new Map(shopItems(shop).map(item=>[item.name,item]));ui.customerCart=(ui.customerCart||[]).filter(line=>byName.has(line.itemName)).map(line=>{const item=byName.get(line.itemName),max=item.unlimited?purchaseLimit(shop):Math.min(purchaseLimit(shop),Math.max(item.count,0));let qty=safeInt(line.qty,1,purchaseLimit(shop),1);qty=Math.max(1,Math.min(qty,Math.max(max,1)));return{...line,label:item.label,price:item.price,image:item.image,unlimited:item.unlimited,count:item.count,qty}})}
function addToCart(itemName,qty=1){const shop=ui.customerShop;if(!shop)return;const item=shopItems(shop).find(row=>row.name===itemName);if(!item)return;const max=item.unlimited?purchaseLimit(shop):Math.min(purchaseLimit(shop),Math.max(item.count,0));if(max<1)return showToast('This item is out of stock.',true);const line=findCartLine(itemName),add=safeInt(qty,1,purchaseLimit(shop),1);if(line){line.qty=Math.min(max,line.qty+add);line.label=item.label;line.price=item.price;line.image=item.image;line.unlimited=item.unlimited;line.count=item.count}else ui.customerCart.push({itemName:item.name,label:item.label,price:item.price,image:item.image,unlimited:item.unlimited,count:item.count,qty:Math.min(max,add)});renderCustomerShop(shop)}
function setCartQty(itemName,value){const line=findCartLine(itemName);if(!line)return;const item=shopItems(ui.customerShop).find(row=>row.name===itemName);if(!item)return;const max=item.unlimited?purchaseLimit(ui.customerShop):Math.min(purchaseLimit(ui.customerShop),Math.max(item.count,0));line.qty=Math.max(1,Math.min(max,safeInt(value,1,purchaseLimit(ui.customerShop),line.qty)));renderCustomerShop(ui.customerShop)}
function changeCartQty(itemName,delta){const line=findCartLine(itemName);if(!line)return;setCartQty(itemName,safeInt(line.qty,1,9999,1)+delta)}
function removeCartItem(itemName){ui.customerCart=(ui.customerCart||[]).filter(line=>String(line.itemName)!==String(itemName));renderCustomerShop(ui.customerShop)}
function renderBag(shop){syncCartAgainstShop(shop);const count=cartItemCount();customerBagCount.textContent=String(count);customerBagSubtotal.textContent=`$${cartSubtotal()}`;customerBagPaymentSummary.textContent=paymentLabel(shop.payment_type||'cash');customerBagPaymentStock.textContent=shop.stock_mode==='infinite'?'∞ stock':'live stock';customerBagEmpty.classList.toggle('hidden',count>0);customerCheckout.disabled=count<1;customerBagItems.innerHTML=(ui.customerCart||[]).map(line=>`<div class="bagItem"><div class="bagThumb">${shopImg(line.image,line.label)}</div><div class="bagItemInfo"><strong>${esc(line.label)}</strong><div class="bagItemControls shopQtyStepper"><button data-action="cartQty" data-item="${esc(line.itemName)}" data-delta="-1" aria-label="Decrease">−</button><input data-action="cartQtyInput" data-item="${esc(line.itemName)}" type="number" min="1" max="${purchaseLimit(shop)}" value="${safeInt(line.qty,1,purchaseLimit(shop),1)}"><button data-action="cartQty" data-item="${esc(line.itemName)}" data-delta="1" aria-label="Increase">+</button></div></div><span class="bagItemPrice">$${safeInt(line.price,0,100000000,0)}</span><button class="bagRemove" data-action="cartRemove" data-item="${esc(line.itemName)}" aria-label="Remove ${esc(line.label)}">${SHOP_ICONS.trash}</button></div>`).join('')}
function renderCategories(shop,luna){customerShopCategories.innerHTML=categoryMeta(luna).map(cat=>`<button class="shopCategory ${ui.customerFilters.category===cat.key?'active':''}" data-action="shopCategory" data-category="${cat.key}"><span class="shopCategoryIcon">${shopIcon(cat.key)}</span><span class="shopCategoryCopy"><strong>${esc(cat.label)}</strong><small>${esc(cat.sub)}</small></span><span class="shopCategoryChevron">${SHOP_ICONS.chevron}</span></button>`).join('')}
function renderPromo(shop,luna){customerShopPromo.innerHTML=luna?`<div class="shopPromoGlow"></div><div class="shopPromoNeon">${SHOP_ICONS.promoLeaf}</div><h3>Plants<br>Make<br>People<br>Happier.</h3><span class="shopPromoRule"></span><p class="shopPromoQuote">Quality supplies<br>for a greener<br>tomorrow.</p>`:`<div class="shopPromoGlow"></div><div class="shopPromoNeon">${SHOP_ICONS.promoLeaf}</div><h3>${esc(shop.label||'Corner Market')}</h3><span class="shopPromoRule"></span><p class="shopPromoQuote">Everything you need,<br>all in one place.</p>`}
function renderCustomerShop(shop){ui.customerShop=shop;if(!Array.isArray(ui.customerCart))ui.customerCart=[];if(!ui.customerFilters)ui.customerFilters={search:'',category:'all',sort:'featured'};if(!(ui.customerFavourites instanceof Set))ui.customerFavourites=new Set();const luna=isLunaLeafShop(shop);shopShell.dataset.theme=luna?'luna':'velora';customerShopKicker.textContent=luna?'VELORA · BOTANICAL DISPENSARY':'VELORA · MARKETPLACE';customerShopBrand.textContent=luna?'Luna Leaf':shop.label;customerShopTitle.textContent=luna?'Rooted in calm. Grown in Velora.':'Independent counter service';customerShopMessage.innerHTML=luna?'<span>A little green sanctuary</span><span>for whatever kind of day you’re having.</span>':'<span>Choose what you need.</span><span>We’ll handle the rest.</span>';customerShopFooter.textContent=luna?'From roots to a brighter tomorrow.':'Independent counter service.';customerShopPayment.textContent=`${paymentLabel(shop.payment_type||'cash')} - ${shop.stock_mode==='infinite'?'∞ stock':'live stock'}`;if(customerShopSearch&&customerShopSearch.value!==ui.customerFilters.search)customerShopSearch.value=ui.customerFilters.search||'';if(customerShopSort&&customerShopSort.value!==ui.customerFilters.sort)customerShopSort.value=ui.customerFilters.sort||'featured';renderCategories(shop,luna);renderPromo(shop,luna);const items=filteredShopItems(shop),showFeatured=(ui.customerFilters.sort||'featured')==='featured'&&!String(ui.customerFilters.search||'').trim();customerShopItems.innerHTML=items.map((i,index)=>{const soldOut=!i.unlimited&&safeInt(i.count,0,999999,0)<1,stock=i.unlimited?'Always stocked':soldOut?'Sold out':safeInt(i.count,0,999999,0)<=3?`Low stock · ${safeInt(i.count,0,999999,0)} left`:`${safeInt(i.count,0,999999,0)} in stock`,inBag=findCartLine(i.name)?.qty||1,featured=showFeatured&&index===0&&!soldOut,fav=ui.customerFavourites.has(i.name);return`<article class="shopCard ${soldOut?'soldOut':''} ${featured?'featured':''}"><div class="shopCardMedia">${featured?'<span class="shopFeaturedBadge">Featured</span>':''}<button class="shopFavourite ${fav?'active':''}" data-action="shopFavourite" data-item="${esc(i.name)}" aria-label="Save item" aria-pressed="${fav}">${SHOP_ICONS.heart}</button>${shopImg(i.image,i.label)}</div><div class="shopCardBody"><div class="shopCardTop"><h3>${esc(i.label)}</h3><span class="shopPrice shopPricePill">$${safeInt(i.price,0,100000000,0)}</span></div><div class="shopMeta"><span class="shopStock ${i.unlimited?'always':''}">${stock}</span><span class="shopUnit">per item</span></div><div class="shopCardControls"><div class="shopQtyStepper"><button data-action="previewQty" data-item="${esc(i.name)}" data-delta="-1" aria-label="Decrease">−</button><input data-action="previewQtyInput" data-item="${esc(i.name)}" type="number" min="1" max="${purchaseLimit(shop)}" value="${inBag}"><button data-action="previewQty" data-item="${esc(i.name)}" data-delta="1" aria-label="Increase">+</button></div><button class="shopAddButton" data-action="addToBag" data-item="${esc(i.name)}" ${soldOut?'disabled':''}>${SHOP_ICONS.leaf}<span>${soldOut?'Sold out':'Add to bag'}</span></button></div></div></article>`}).join('')||'<div class="shopEmpty"><strong>Fresh stock is on the way.</strong><span>Try another category or check back soon.</span></div>';renderBag(shop)}
async function checkoutBag(){if(!ui.customerShop||!ui.customerCart?.length)return;customerCheckout.disabled=true;for(const line of[...ui.customerCart]){const endpoint=ui.customerShop.source_type==='point'?'purchasePointShop':'purchaseBusiness',payload=ui.customerShop.source_type==='point'?{pointId:ui.customerShop.point_id||ui.customerShop.id,itemName:line.itemName,count:safeInt(line.qty,1,purchaseLimit(ui.customerShop),1)}:{shopId:ui.customerShop.id,itemName:line.itemName,count:safeInt(line.qty,1,purchaseLimit(ui.customerShop),1)},res=await post(endpoint,payload);if(!res.ok){showToast(res.error||`Purchase failed for ${line.label}.`,true);customerCheckout.disabled=false;if(res.shop)renderCustomerShop(res.shop);return}if(res.shop){ui.customerShop=res.shop;syncCartAgainstShop(res.shop)}}ui.customerCart=[];if(ui.customerShop)renderCustomerShop(ui.customerShop);customerCheckout.disabled=false;showToast('Purchase complete.')}
window.addEventListener('message',e=>{const{action,payload}=e.data||{};if(action==='openAdmin'){ui.mode='admin';ui.bootstrap=payload;ui.customerShop=null;setAppVisible(true);shopShell.classList.add('hidden');adminShell.classList.remove('hidden');if(!ui.drafts.job)ui.drafts.job=defaultDraft('job');renderAdmin()}if(action==='openCustomerShop'){ui.mode='customer';ui.customerFilters={search:'',category:'all',sort:'featured'};ui.customerCart=[];setAppVisible(true);adminShell.classList.add('hidden');shopShell.classList.remove('hidden');renderCustomerShop(payload)}if(action==='close'){setAppVisible(false);adminShell.classList.add('hidden');shopShell.classList.add('hidden')}if(action==='hideForPlacement'){setAppVisible(false);adminShell.classList.add('hidden')}if(action==='showAfterPlacement'&&ui.mode==='admin'){setAppVisible(true);adminShell.classList.remove('hidden')}if(action==='placementResult'&&payload){const d=ui.drafts.npc;d.position=payload;renderEditor()}if(action==='pointPlacementResult'&&payload){const d=ui.drafts.point;d.position=payload;renderEditor()}});
