 if(a==='new'){ui.workspace.editor=null;const k=ui.tab==='jobs'?'job':ui.tab==='points'?'point':ui.tab==='npcs'?'npc':'business';setDraft(defaultDraft(k),k);if(k==='job')ui.workspace.section='overview';renderAdmin();return}
 if(a==='edit'){const r=findEntity(b.dataset.id);if(!r)return;ui.workspace.editor=null;const k=ui.tab==='jobs'?'job':ui.tab==='points'?'point':ui.tab==='npcs'?'npc':'business';const d=clone(r);if(k==='point')d.position={x:d.x,y:d.y,z:d.z,heading:d.heading};if(k==='npc')d.position={x:d.x,y:d.y,z:d.z,heading:d.heading};if(k==='business')d.stock={x:d.stock_x,y:d.stock_y,z:d.stock_z};setDraft(d,k);if(k==='job'){ui.workspace.jobId=d.id;ui.workspace.section='overview'}renderAdmin();return}
 if(a==='workspaceSection'){ui.workspace.section=b.dataset.section;ui.workspace.editor=null;renderEditor();return}
 if(a==='newLinked'){const kind=b.dataset.kind,job=ui.drafts.job?.job_name;if(kind==='points'||kind==='point'){ui.drafts.point={...defaultDraft('point'),job_name:job};ui.workspace.editor='point'}else if(kind==='fleet'){ui.drafts.fleet={...defaultDraft('fleet'),job_name:job};ui.workspace.editor='fleet'}else{ui.drafts.blip={...defaultDraft('blip'),job_name:job};ui.workspace.editor='blip'}renderEditor();return}
 if(a==='editLinked'){const kind=b.dataset.kind,key=kind==='points'||kind==='point'?'points':kind==='blip'?'blips':'fleet',draftKey=kind==='points'||kind==='point'?'point':kind==='blip'?'blip':'fleet',row=findRowById(ui.bootstrap.state[key],b.dataset.id);if(row){const d=clone(row);if(draftKey==='point'||draftKey==='blip')d.position={x:d.x,y:d.y,z:d.z,heading:d.heading};ui.drafts[draftKey]=d;ui.workspace.editor=draftKey;renderEditor()}return}
 if(a==='backBusiness'){ui.workspace.editor=null;renderEditor();return} if(a==='newShop'){ui.drafts.shop={...defaultDraft('shop'),business_job:ui.drafts.business?.job_name||''};ui.workspace.editor='shop';renderEditor();return} if(a==='editShop'){const s=findRowById(ui.bootstrap.state.shops,b.dataset.id);if(s){ui.drafts.shop=clone(s);ui.workspace.editor='shop';renderEditor()}return}
